CREATE TABLE IF NOT EXISTS blobs (digest TEXT PRIMARY KEY, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), media_type TEXT NOT NULL, path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS saved_copies (id TEXT PRIMARY KEY, bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE, source_url TEXT NOT NULL, effective_url TEXT NOT NULL, url_revision INTEGER NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('html','pdf')), primary_blob_digest TEXT NOT NULL REFERENCES blobs(digest), total_size_bytes INTEGER NOT NULL CHECK(total_size_bytes>=0), primary_media_type TEXT NOT NULL, captured_at TEXT NOT NULL, warning_count INTEGER NOT NULL DEFAULT 0 CHECK(warning_count>=0));
CREATE TABLE IF NOT EXISTS capture_attempts (id TEXT PRIMARY KEY, bookmark_id TEXT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE, state TEXT NOT NULL CHECK(state IN ('queued','running','available','failed','cancelled')), error_code TEXT, error_detail TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'queued', run_after TEXT NOT NULL, leased_until TEXT, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
